parameters.jsCode:
// 1. Fetch raw text from the previous node
const inputItem = $input.item.json;
let rawText = inputItem.output || "";

// INITIALIZE FLAGS AND DATA OBJECTS AT THE TOP (FIXES REFERENCE ERROR)
let parsedData = {};
let isIntentRoute = false;

// Normalize line breaks and spaces
rawText = rawText.replace(/\\n/g, '\n').replace(/\\r/g, '\r').trim();

// 2. MATRIX PARSING ENGINE: Check if text is an Intent-based JSON Block
if (rawText.includes('{') && rawText.includes('}')) {
    try {
        // Isolate the JSON string structure out of raw text prose
        const startJson = rawText.indexOf('{');
        const endJson = rawText.lastIndexOf('}') + 1;
        const jsonString = rawText.substring(startJson, endJson);
        const cleanJson = JSON.parse(jsonString);

        // Normalize keys to lowercase to avoid case mismatches
        for (let key in cleanJson) {
            parsedData[key.toLowerCase().replace(/[\s_\-]/g, '')] = String(cleanJson[key]);
        }

        // If it successfully parsed and contains an intent field, flag it for the True path
        if (parsedData["intent"]) {
            isIntentRoute = true;
        }
    } catch (e) {
        // If JSON parsing fails due to bad syntax, fall back to line processing
        parseTextByLines(rawText, parsedData);
    }
} else {
    parseTextByLines(rawText, parsedData);
}

// Fallback plain-text parsing algorithm
function parseTextByLines(text, dataObj) {
    const lines = text.split(/[\n\r,]+/);
    for (let line of lines) {
        const colonIndex = line.indexOf(':');
        if (colonIndex !== -1) {
            let key = line.substring(0, colonIndex).replace(/[\\"\*\{\}]/g, '').trim().toLowerCase().replace(/[\s_\-]/g, '');
            let value = line.substring(colonIndex + 1).replace(/[\\"\{\}]/g, '').trim();
            if (value.endsWith(',')) value = value.slice(0, -1).trim();

            if (key && value !== "" && !value.startsWith('[')) {
                dataObj[key] = value;
            }
        }
    }
    if (dataObj["intent"] === "booking confirmed" || dataObj["intent"] === "confirmed" || dataObj["intent"] === "booking rescheduled") {
        isIntentRoute = true;
    }
}

// 3. DATA EXTRACTION LAYER
const intent = parsedData["intent"] || (isIntentRoute ? "booking confirmed" : "normal chat");
const patientName = parsedData["patientname"] || parsedData["patient name"] || "";
const department = parsedData["department"] || "";
const doctorName = parsedData["doctorname"] || parsedData["doctor name"] || "";
const issue = parsedData["issue"] || "";
const gender = parsedData["gender"] || "";
const fee = parsedData["fee"] || "2500";
const calendarId = parsedData["calendarid"] || parsedData["calendar id"] || "";
const eventId = parsedData["eventid"] || null;
const description = parsedData["description"] || "";

// Normalize Mobile Format (Strictly starting with 92, dropping leading 0)
let rawMobile = parsedData["mobile"] || parsedData["mobilenumber"] || "";
let cleanMobile = rawMobile.replace(/[^\d]/g, '');
if (cleanMobile.startsWith('0')) {
    cleanMobile = '92' + cleanMobile.substring(1);
} else if (!cleanMobile.startsWith('92') && cleanMobile.length > 0) {
    cleanMobile = '92' + cleanMobile;
}

// 4. ISO DATE/TIME COMPILATION ENGINE
const rawDate = parsedData["date"] || parsedData["newdate"] || "2026-05-28";
const startTimeStr = parsedData["starttime"] || "";
const endTimeStr = parsedData["endtime"] || "";

// Hybrid Time Converter: Intelligently accepts both "17:30" and "05:30 PM" formats safely
function convertTimeTo24h(timeStr) {
    if (!timeStr) return "00:00:00";

    // Clean up spaces
    let cleanTime = timeStr.trim();

    // Strategy A: Check if string is already formatted as clean 24H (HH:mm or HH:mm:ss)
    const standard24hMatch = cleanTime.match(/^(\d{1,2}):(\d{2})(?::\d{2})?$/);
    if (standard24hMatch) {
        let h = parseInt(standard24hMatch[1], 10);
        let m = standard24hMatch[2];
        if (h >= 0 && h < 24) {
            return `${String(h).padStart(2, '0')}:${m}:00`;
        }
    }

    // Strategy B: Handle legacy AM/PM strings
    const amPmMatch = cleanTime.match(/^(\d{1,2}):(\d{2})\s*(AM|PM)$/i);
    if (amPmMatch) {
        let hours = parseInt(amPmMatch[1], 10);
        const minutes = amPmMatch[2];
        const modifier = amPmMatch[3].toUpperCase();
        if (modifier === 'PM' && hours < 12) hours += 12;
        if (modifier === 'AM' && hours === 12) hours = 0;
        return `${String(hours).padStart(2, '0')}:${minutes}:00`;
    }

    return "00:00:00"; // Fallback safe midnight state
}

const googleStartDate = `${rawDate}T${convertTimeTo24h(startTimeStr)}+05:00`;
const googleEndDate = `${rawDate}T${convertTimeTo24h(endTimeStr)}+05:00`;

// 5. PACKAGING SYSTEM RESILIENT OUTBOUND PAYLOAD
const outputData = {
    isIntent: isIntentRoute,
    intent: intent,
    patientName: patientName,
    mobileNumber: cleanMobile,
    department: department,
    doctorName: doctorName,
    issue: issue,
    age: (parsedData["age"] || "").replace(/[^\d]/g, '').trim(),
    gender: gender,
    date: rawDate, 
    startTime: startTimeStr,
    endTime: endTimeStr,
    googleStartDate: googleStartDate,
    googleEndDate: googleEndDate,
    fee: fee.includes('PKR') ? fee : `${fee} PKR`,
    calendarId: calendarId,
    eventId: eventId,
    summary: patientName ? `${patientName} - ${issue || 'Consultation'}` : "Appointment Details",

    // CLEANED UP DESCRIPTION FIELDS
    description: description && description.length > 15 ? description : 
`Patient Name: ${patientName || 'Not Specified'}
Gender: ${gender || 'Not Specified'}
Age: ${(parsedData["age"] || "").replace(/[^\d]/g, '').trim() || 'Not Specified'}
Contact: ${cleanMobile}
Assigned Doctor: ${doctorName || 'Duty Doctor'}
Department: ${department || 'General Medicine'}
Consultation Fee: ${fee.includes('PKR') ? fee : `${fee} PKR`}`,

    conversationalReply: !isIntentRoute ? rawText : "" 
};

return { json: outputData };

// 1. Get the incoming data item
const incomingItems = $input.all();
let basePayload = {};

if (incomingItems && incomingItems.length > 0) {
  basePayload = incomingItems[0].json;
}

// 2. Extract the query string accurately from any incoming path variation
// This checks 'query', 'User Message', or 'text' based on your workflow paths
let finalQuery = basePayload["query"] || basePayload["User Message"] || basePayload["text"] || "";

// 3. Determine the Message Type dynamically
let messageType = basePayload["Message Type"] || (basePayload["text"] ? "audio" : "text");

// 4. Return ONLY the two requested keys in the output payload
return [{
  json: {
    "query": finalQuery,
    "Message Type": messageType
  }
}];

// 1. Target the incoming data from the active item loop
const items = $json;

// 2. Grab the text output sent from your AI Agent
const messageText = items.output || "";

// 3. Fallback to your current state tracking routing type
let determinedType = items["Message Type"] || "audio";

// 4. Convert text to lowercase once for accurate string checking
const lowerText = messageText.toLowerCase();

// 5. Check Rule A: Explicit Clinic Action JSON Intents (Kept as is)
const hasJsonIntent = lowerText.includes("booking confirmed") || 
                      lowerText.includes("booking rescheduled") || 
                      lowerText.includes("booking cancelled");

// 6. Check Rule B: Core Patient & Clinic Confirmation Headers
const hasSummaryLayout = lowerText.includes("patient name:") || 
                         lowerText.includes("mobile number:") || 
                         lowerText.includes("confirmation summary:") ||
                         lowerText.includes("shall i book?");

// 7. Check Rule C: Slot Availability Announcements
const hasSlotList = lowerText.includes("available slots:") || 
                    lowerText.includes("slot on") || 
                    lowerText.includes("is unavailable");

// 8. If any structured confirmation layout or slot list matches, force Text route
if (hasJsonIntent || hasSummaryLayout || hasSlotList) {
    determinedType = "text";
}

// 9. Output the clean object back to your downstream workflow nodes
return {
    "output": messageText,
    "Message Type": determinedType,
    "Customer Number": items["Customer Number"] || "",
    "Session ID": items["Session ID"] || "",
    "Current_Department": items["Current_Department"] || "Clinic Deptt"
};

// 1. Get Base64 from Gemini
const base64Data = $json.candidates[0].content.parts[0].inlineData.data;
const pcmBuffer = Buffer.from(base64Data, 'base64');

// 2. Create WAV Header (44 bytes) so Cloudinary recognizes it
const wavHeader = Buffer.alloc(44);
wavHeader.write('RIFF', 0);
wavHeader.writeUInt32LE(36 + pcmBuffer.length, 4);
wavHeader.write('WAVE', 8);
wavHeader.write('fmt ', 12);
wavHeader.writeUInt32LE(16, 16);
wavHeader.writeUInt16LE(1, 20); // PCM format
wavHeader.writeUInt16LE(1, 22); // Mono
wavHeader.writeUInt32LE(24000, 24); // Sample Rate (Gemini is 24kHz)
wavHeader.writeUInt32LE(24000 * 2, 28); // Byte Rate
wavHeader.writeUInt16LE(2, 32); // Block Align
wavHeader.writeUInt16LE(16, 34); // Bits per sample
wavHeader.write('data', 36);
wavHeader.writeUInt32LE(pcmBuffer.length, 40);

// 3. Combine Header + Raw Data
const finalBuffer = Buffer.concat([wavHeader, pcmBuffer]);

// 4. Register as a file for Cloudinary
const binaryData = await this.helpers.prepareBinaryData(
    finalBuffer, 
    'appointment_voice.mp3', 
    'audio/mpeg'
);

return [
  {
    json: { resource_type: "video" },
    binary: { data: binaryData }
  }
];
